from pathlib import Path
from interaction_components import robot_explorer, upgrade_explorer
root=Path(__file__).parent/'dist'
fire='<svg class="fire-mark" viewBox="0 0 22 28" aria-hidden="true"><path d="M9 1h4v5h4v4h3v12H3V10h3V6h3" fill="#d98a45"/><path d="M10 10h4v6h3v6H7v-6h3" fill="#efd293"/><path d="M1 24h8v3H1m12-3h8v3h-8" fill="#93a181"/></svg>'
def header(active=''):
    return f'''<a class="skip" href="#main">Skip to content</a><header class="site-header"><div class="wrap nav-inner"><a class="wordmark" href="/" aria-label="Yichen Wang portfolio home"><span>Port</span>{fire}<em>folio</em></a><nav id="navigation" class="nav-links" aria-label="Main navigation"><a href="/" {'aria-current="page"' if active=='home' else ''}>Home</a><a href="/projects/" {'aria-current="page"' if active in ('project','projects','robotics','hashland') else ''}>Projects</a><a href="/about/" {'aria-current="page"' if active=='about' else ''}>About / CV</a></nav></div></header>'''
def footer():
    return '''<footer class="footer"><div class="wrap"><div class="footer-top"><p class="footer-quote">Thanks for stopping by.</p><a class="text-link" href="/about/">A little more about me <span aria-hidden="true">↗</span></a></div><div class="footer-bottom"><span>© 2026 Yichen Wang</span><span><span class="leaf" aria-hidden="true">✦</span> Yichen Wang · Portfolio</span></div></div></footer>'''
def page(title,desc,body,active=''):
    extra='<link rel="stylesheet" href="/gamebuddy-system.css"><script defer src="/gamebuddy-system.js"></script>' if active in ('home','project') else ''
    extra+='<link rel="stylesheet" href="/robotics.css">' if active in ('home','robotics','projects') else ''
    extra+='<link rel="stylesheet" href="/hashland.css">' if active in ('home','hashland','projects') else ''
    extra+='<link rel="stylesheet" href="/interactions.css"><script defer src="/interactions.js"></script>' if active in ('home','project','robotics','hashland') else ''
    extra+='<link rel="stylesheet" href="/hashland-media.css">' if active=='hashland' else ''
    extra+='<link rel="stylesheet" href="/home-projects.css">' if active=='home' else ''
    detail_theme=active in ('project','robotics','hashland')
    extra+='<link rel="stylesheet" href="/project-themes.css">' if detail_theme else ''
    extra+='<link rel="stylesheet" href="/hashland-case-study.css">' if active=='hashland' else ''
    body_class=f'project-page project-{"gamebuddy" if active=="project" else active}' if detail_theme else ''
    body_attr=f' class="{body_class}"' if body_class else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title}</title><meta name="description" content="{desc}"><meta name="theme-color" content="#132c2a"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css">{extra}<link rel="stylesheet" href="/reactivity.css"><script defer src="/reactivity.js"></script><script defer src="/landscape.js"></script><script defer src="/orbit.js"></script><script defer src="/app.js"></script></head><body{body_attr}>{header(active)}{body}{footer()}</body></html>'''
def scene(extra=''):
    return f'<canvas class="landscape" data-landscape aria-hidden="true" {extra}></canvas>'
system_graph=(root/'assets/gamebuddy-architecture.svg').read_text()
home_showcase=(root.parent/'home-gamebuddy.html').read_text().replace('{{SYSTEM_GRAPH}}',system_graph)
