home=f'''<main id="main"><section class="hero" aria-labelledby="intro-title">{scene()}<div class="wrap hero-content hero-layout"><div class="hero-bio"><h1 class="hero-title" id="intro-title">Exploring Human–AI Interaction<br><em>Beyond Chat.</em></h1><div class="hero-copy"><p class="hero-name">I’m <strong>Yichen Wang</strong>.</p><p>I earned a master’s degree in Information Science from Cornell University in 2024 and two bachelor’s degrees in Physics and Digital Media from the University of Rochester, graduating with highest distinction.</p><p>I worked as a full-stack AI agent developer and later as lead product manager for the WALL-E companion robot.</p><p>I’m now exploring how to make human–AI interaction more natural and human-like, especially through AI companions in video games.</p></div><div class="hero-actions"><a class="button" href="#work">Explore my work <span aria-hidden="true">↓</span></a><a class="text-link" href="/about/">Background &amp; CV <span aria-hidden="true">↗</span></a></div></div><figure class="portrait-orbit" aria-label="Yichen Wang and his areas of work" data-orbit><img class="hero-portrait" src="/assets/yichen-wang.jpg" width="1254" height="1254" alt="Yichen Wang smiling, wearing glasses and a brown suit" fetchpriority="high"><ul class="orbit-labels" aria-label="Areas of work"><li class="orbit-label" data-orbit-label><span class="orbit-dot" aria-hidden="true"></span>Human-AI Interaction</li><li class="orbit-label" data-orbit-label><span class="orbit-dot" aria-hidden="true"></span>AI-Companion Product Manager</li><li class="orbit-label" data-orbit-label><span class="orbit-dot" aria-hidden="true"></span>Full-Stack Developer</li><li class="orbit-label" data-orbit-label><span class="orbit-dot" aria-hidden="true"></span>Reinforcement Learning</li></ul></figure></div><button class="hero-motion-icon" data-motion-toggle aria-pressed="false" aria-label="Pause animation" title="Pause animation"><span data-motion-symbol aria-hidden="true">Ⅱ</span></button></section>
<section class="featured-projects" id="work" aria-labelledby="work-title"><div class="wrap featured-projects-heading"><h2 id="work-title">Featured Projects</h2></div>
{home_showcase}
{home_robotics}
{home_hashland}
</section>
</main>'''
project=(root.parent/'gamebuddy-page.html').read_text().replace('{{SYSTEM_GRAPH}}',system_graph)
about=f'''<main id="main"><section class="page-hero"><div class="wrap"><span class="eyebrow">Background / Experience</span><h1>Hi, I’m Yichen<span style="color:var(--gold)">.</span></h1><p class="lead">An AI builder with a background in information science, physics, digital media, and robotics products.</p></div></section><section class="chapter"><div class="wrap about-grid"><aside><p class="about-statement">I’m interested in the space between what AI can do and how people want to work with it.</p><p class="body-copy">Since graduating from Cornell, I’ve worked in AI agent development and led hardware and software product management at a robotics startup. I’m now building GameBuddy.</p><a class="text-link" href="/projects/gamebuddy/">Meet GameBuddy <span aria-hidden="true">↗</span></a></aside><div><section class="about-block" aria-labelledby="education"><h2 id="education">Education</h2><div class="timeline-row"><span class="year">2024</span><div><h3>Cornell University</h3><p>Master of Professional Studies in Information Science</p></div></div><div class="timeline-row"><span class="year">2023</span><div><h3>University of Rochester</h3><p>B.A. · Physics &amp; Astronomy / Digital Media Studies</p></div></div></section><section class="about-block" aria-labelledby="experience"><h2 id="experience">Experience</h2><div class="timeline-row"><span class="year">NOW</span><div><h3>GameBuddy</h3><p>Independent development of an AI-powered gaming companion.</p></div></div><div class="timeline-row"><span class="year">AI</span><div><h3>AI agent development</h3><p>Experience building AI agents and interactive products.</p></div></div><div class="timeline-row"><span class="year">ROBOTICS</span><div><h3>Hardware &amp; software product management</h3><p>Product leadership at a robotics startup.</p><a class="rb-inline-link" href="/projects/robotics/">Wall-E Companion Robot ↗</a></div></div></section><section id="cv" class="cv-notice" aria-label="CV availability">The downloadable CV and contact links will be added here.</section></div></div></section></main>'''
(root/'index.html').write_text(page('Yichen Wang — AI Builder & HCI Explorer','Yichen Wang builds AI agents and interactive experiences. Explore GameBuddy and a background in Cornell information science and robotics.',home,'home'))
